    return ''.join(result)

def a_snake(s):
    if not s:
        return ""
    result = []
    prev_is_upper = False
    for char in s:
        if char.isupper():
            if prev_is_upper:
                result.append("-")
            result.append(char.lower())
            prev_is_upper = False
        else:
            result.append(char.lower())
            prev_is_upper = char.isupper()
    return "".join(result)

